234			wantBytes := appendFrames(t, path, bad, follow)
235	
236			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
237				"recover incidents", "itself", `"bob"`)
238		})
239	}
240	
241	// TestServeIllegalHandoverBeforeTornTailKeepsEveryByte covers the recovery
242	// ordering regression: a complete illegal handover record followed by an
243	// unfinished trailing write. Startup must reject the handover and leave the
244	// log byte-for-byte intact — the torn tail must not be trimmed before the
245	// failure, and no complete record may be rewritten or dropped. Both torn
246	// shapes are covered: a partial frame header, and a full header whose
247	// payload never completely landed.
248	func TestServeIllegalHandoverBeforeTornTailKeepsEveryByte(t *testing.T) {
249		stamp := func(sec int) time.Time {
250			return time.Date(2026, 10, 1, 12, 0, 0, sec, time.UTC)
251		}
252		frame := func(t *testing.T, record incidents.Record) []byte {
253			t.Helper()
254			payload, err := incidents.MarshalRecord(record)
255			if err != nil {
256				t.Fatal(err)
257			}
258			out := make([]byte, 8+len(payload))
259			binary.BigEndian.PutUint32(out[0:4], uint32(len(payload)))
260			binary.BigEndian.PutUint32(out[4:8], crc32.ChecksumIEEE(payload))
261			copy(out[8:], payload)
262			return out
263		}
264		// seed writes one legal incident through the live server and hard kills
265		// it, returning the incident log path and its confirmed bytes.
266		seed := func(t *testing.T, assignBob bool) (string, string) {
267			t.Helper()
268			dataDir := t.TempDir()
269			first := startServer(t, dataDir)
270			postIncident(t, first, `{"id":"INC-9","title":"t","service":"gateway","operator":"Alice"}`)
271			if assignBob {
272				if s, _ := postIncidentAction(t, first, "INC-9",
273					`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
274					t.Fatalf("add bob status %d", s)
275				}
276			}
277			first.signal(t, syscall.SIGKILL)
278			first.waitExit(t, -1)
279			waitTCPPortClosed(t, first.addr)
280			return dataDir, filepath.Join(dataDir, "incidents.log")
281		}
282	
283		t.Run("non-participant handover ahead of a partial header", func(t *testing.T) {
284			dataDir, path := seed(t, true)
285	
286			bad := incidents.NewActionRecord(incidents.Request{
287				IncidentID: "INC-9", ActionID: "o1", Operator: "alice",
288				ExpectedVersion: 2, Type: incidents.ActionAssignOwner, Content: "carol",
289			}, stamp(1))
290			existing, err := os.ReadFile(path)
291			if err != nil {
292				t.Fatal(err)
293			}
294			// The tail is only the first three bytes of the next frame's header.
295			torn := frame(t, incidents.NewActionRecord(incidents.Request{
296				IncidentID: "INC-9", ActionID: "n1", Operator: "alice",
297				ExpectedVersion: 3, Type: incidents.ActionNote, Content: "never finished",
298			}, stamp(2)))[:3]
299			wantBytes := append(append(append([]byte{}, existing...), frame(t, bad)...), torn...)
300			if err := os.WriteFile(path, wantBytes, 0o644); err != nil {
301				t.Fatal(err)
302			}
303	
304			// The error must name the handover rule and target, not the torn tail.
305			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
306				"recover incidents", "non-participant", `"carol"`)
307			// A retry fails identically: nothing was trimmed or rewritten.
308			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
309				"recover incidents", "non-participant", `"carol"`)
310		})
311	
312		t.Run("self handover ahead of a header-complete torn payload", func(t *testing.T) {
313			dataDir, path := seed(t, false)
314	
315			bad := incidents.NewActionRecord(incidents.Request{
316				IncidentID: "INC-9", ActionID: "o1", Operator: "alice",
317				ExpectedVersion: 1, Type: incidents.ActionAssignOwner, Content: "Alice",
318			}, stamp(1))
319			existing, err := os.ReadFile(path)
320			if err != nil {
321				t.Fatal(err)
322			}
323			// The tail has a complete header but only half of its payload.
324			tornFrame := frame(t, incidents.NewActionRecord(incidents.Request{
325				IncidentID: "INC-9", ActionID: "n1", Operator: "alice",
326				ExpectedVersion: 2, Type: incidents.ActionNote, Content: "never finished",
327			}, stamp(2)))
328			torn := tornFrame[:8+(len(tornFrame)-8)/2]
329			wantBytes := append(append(append([]byte{}, existing...), frame(t, bad)...), torn...)
330			if err := os.WriteFile(path, wantBytes, 0o644); err != nil {
331				t.Fatal(err)
332			}
333	
334			expectServeFailsOnIncidentLog(t, dataDir, wantBytes, path,
335				"recover incidents", "itself", `"Alice"`)
336		})
337	}
338	
339	// TestServeLegalIncidentHistoryWithTornTailStarts confirms the torn-tail
340	// rule still applies when every complete record is legal: startup trims only
341	// the unfinished trailing write, and the incident recovers to the last
342	// complete record's state — owner, participants, version, and history
343	// unchanged, with the tail neither applied nor fabricated into history.
344	func TestServeLegalIncidentHistoryWithTornTailStarts(t *testing.T) {
345		dataDir := t.TempDir()
346		first := startServer(t, dataDir)
347		postIncident(t, first, `{"id":"INC-10","title":"t","service":"gateway","operator":"Alice"}`)
348		if s, _ := postIncidentAction(t, first, "INC-10",
349			`{"action_id":"p1","operator":"alice","expected_version":1,"action":"add_participant","participant":"bob"}`); s != http.StatusOK {
350			t.Fatalf("add bob status %d", s)
351		}
352		if s, _ := postIncidentAction(t, first, "INC-10",
353			`{"action_id":"o1","operator":"alice","expected_version":2,"action":"assign_owner","participant":"bob"}`); s != http.StatusOK {
354			t.Fatalf("assign bob status %d", s)
355		}
356		first.signal(t, syscall.SIGKILL)
357		first.waitExit(t, -1)
358		waitTCPPortClosed(t, first.addr)
359	
360		path := filepath.Join(dataDir, "incidents.log")
361		complete, err := os.ReadFile(path)
362		if err != nil {
363			t.Fatal(err)
364		}
365		// A torn tail: a full header plus only part of an assign_owner payload.
366		tornRecord := incidents.NewActionRecord(incidents.Request{
367			IncidentID: "INC-10", ActionID: "o2", Operator: "alice",
368			ExpectedVersion: 3, Type: incidents.ActionAssignOwner, Content: "Alice",
369		}, time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC))
370		tornPayload, err := incidents.MarshalRecord(tornRecord)
371		if err != nil {
372			t.Fatal(err)
373		}
374		torn := make([]byte, 8+6)
375		binary.BigEndian.PutUint32(torn[0:4], uint32(len(tornPayload)))
376		binary.BigEndian.PutUint32(torn[4:8], crc32.ChecksumIEEE(tornPayload))
377		copy(torn[8:], tornPayload[:6])
378		if err := os.WriteFile(path, append(append([]byte{}, complete...), torn...), 0o644); err != nil {
379			t.Fatal(err)
380		}
381	
382		second := startServer(t, dataDir)
383		status, got := getIncident(t, second, "INC-10")
384		if status != http.StatusOK {
385			t.Fatalf("get after torn-tail restart %d", status)
386		}
387		if got["owner"] != "bob" || got["status"] != "open" || incNumber(got["version"]) != 3 {
388			t.Fatalf("recovered head must match the last complete record: %v", got)
389		}
390		members, _ := got["participants"].([]any)
391		if len(members) != 2 || members[0] != "Alice" || members[1] != "bob" {
392			t.Fatalf("recovered participants: %v", got["participants"])
393		}
394		history, _ := got["history"].([]any)
395		if len(history) != 3 {
396			t.Fatalf("the torn tail must not become a history entry: %v", got["history"])
397		}
398		last := history[2].(map[string]any)
399		if last["action"] != "assign_owner" || last["action_id"] != "o1" || incNumber(last["version"]) != 3 {
400			t.Fatalf("last history entry: %v", last)
401		}
402	
403		// Only the torn bytes were dropped; every complete record is untouched.
404		trimmed, err := os.ReadFile(path)
405		if err != nil {
406			t.Fatal(err)
407		}
408		if !bytes.Equal(trimmed, complete) {
409			t.Fatal("startup must trim exactly the torn tail and keep every complete record")
410		}
411	
412		// The action the torn write hinted at never happened: Alice is not the
413		// owner, and a fresh handover to Alice commits as version 4.
414		if s, r := postIncidentAction(t, second, "INC-10",
415			`{"action_id":"o2","operator":"alice","expected_version":3,"action":"assign_owner","participant":"Alice"}`); s != http.StatusOK || incNumber(r["version"]) != 4 {
416			t.Fatalf("handover after trim %d %v", s, r)
417		}
418		second.signal(t, syscall.SIGTERM)
419		second.waitExit(t, 0)
420	}
421	
422	// expectServeFailsOnIncidentLog runs serve against dataDir, requires a
423	// non-zero exit without a readiness line, checks that the startup error
424	// contains every want fragment, and verifies the incident log file is
425	// byte-for-byte unchanged.
426	func expectServeFailsOnIncidentLog(t *testing.T, dataDir string, wantBytes []byte, path string, want ...string) {
427		t.Helper()
428		logs := &safeBuffer{}
429		proc := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
430		proc.Stdout = logs
431		proc.Stderr = logs
432		if err := proc.Start(); err != nil {
433			t.Fatal(err)
434		}
435		done := make(chan error, 1)
436		go func() { done <- proc.Wait() }()
437		ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
438		defer cancel()
439		select {
440		case err := <-done:
441			if err == nil {
442				t.Fatal("an illegal handover record must prevent startup")
443			}
444			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
445				t.Fatalf("startup must exit non-zero: %v", err)
446			}
447		case <-ctx.Done():
448			proc.Process.Kill()
449			t.Fatalf("server stayed up despite an illegal handover record; output:\n%s", logs.String())
450		}
451	
452		out := logs.String()
453		for _, fragment := range want {
454			if !strings.Contains(out, fragment) {
455				t.Fatalf("startup error must contain %q:\n%s", fragment, out)
456			}
457		}
458		if strings.Contains(out, "listening on") {
459			t.Fatalf("failed startup must not announce readiness:\n%s", out)
460		}
461	
462		after, err := os.ReadFile(path)
463		if err != nil {
464			t.Fatal(err)
465		}
466		if !bytes.Equal(after, wantBytes) {
467			t.Fatal("failed startup must not modify the incident log, complete offending frame included")
468		}
469	}
