// seededTimes returns n strictly increasing timestamps starting at a fixed
// instant, for replay records that must preserve saved times.
func seededTimes(n int) []time.Time {
	base := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
	times := make([]time.Time, n)
	for i := range times {
		times[i] = base.Add(time.Duration(i+1) * time.Nanosecond)
	}
	return times
}

