	otherEvs, _ := other["events"].([]any)
	if len(otherEvs) != 1 || otherEvs[0].(map[string]any)["id"] != "e1" {
		t.Fatalf("INC-12 link must survive: %v", other["events"])
	}

	// Idempotent unlink retry after restart: first result (v4), no change.
